export function hasRadioReport(before,after){const serial=before.world?.serial||0;return (after.world?.feed||[]).some(r=>Number(r.id.slice(1))>serial&&!r.actor.includes('玩家')&&['通知','回報','完成回報','同事回報','系統決策','請求協調','接手確認','來源差異','後續影響','連帶影響'].includes(r.type));}
// Original browser-synthesized sketch. No streamed music, voice samples, or autoplay.
export function createAudio(getSettings,onError){return {
 ctx:null,gain:null,musicGain:null,voices:[],mood:'calm',nextNote:0,
 init(){if(this.ctx)return;try{this.ctx=new (window.AudioContext||window.webkitAudioContext)();const ctx=this.ctx;this.gain=ctx.createGain();this.gain.gain.value=0;this.gain.connect(ctx.destination);this.musicGain=ctx.createGain();this.musicGain.gain.value=0;this.musicGain.connect(ctx.destination);
 const low=ctx.createOscillator(),g=ctx.createGain();low.frequency.value=74;g.gain.value=.06;low.connect(g);g.connect(this.gain);low.start();
 const buffer=ctx.createBuffer(1,ctx.sampleRate*4,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.5;const src=ctx.createBufferSource(),f=ctx.createBiquadFilter(),ng=ctx.createGain();src.buffer=buffer;src.loop=true;f.type='lowpass';f.frequency.value=320;ng.gain.value=.08;src.connect(f);f.connect(ng);ng.connect(this.gain);src.start();
 for(const hz of [55,82.4069,110]){const o=ctx.createOscillator(),v=ctx.createGain();o.type='sine';o.frequency.value=hz;v.gain.value=.018;o.connect(v);v.connect(this.musicGain);o.start();this.voices.push(o);}
 }catch{onError('這個瀏覽器無法啟用合成聲音，文字回報仍可使用。');}},
 setVolume(){if(!this.ctx)return;const s=getSettings(),hidden=document.hidden;this.gain.gain.setTargetAtTime(!hidden&&s.sound?s.volume:0,this.ctx.currentTime,.3);this.musicGain.gain.setTargetAtTime(!hidden&&s.music?s.musicVolume*(this.reading?.45:1):0,this.ctx.currentTime,1.2);},
 async resume(){const s=getSettings();if(!s.sound&&!s.music)return;this.init();if(this.ctx?.state==='suspended')await this.ctx.resume();this.setVolume();},
 scene(s,reading=false){if(!this.ctx)return;this.reading=reading;const night=s.time>=1080||s.time<450;this.mood=s.activeIncident||s.world?.scenes?.[s.location]?.kind==='anomaly'?'uneasy':night?'night':'calm';const hz=this.mood==='uneasy'?[55,77.7817,110]:this.mood==='night'?[55,73.4162,110]:[55,82.4069,110];this.voices.forEach((o,i)=>o.frequency.setTargetAtTime(hz[i],this.ctx.currentTime,3));this.setVolume();const settings=getSettings();if(!settings.music||document.hidden||this.ctx.currentTime<this.nextNote)return;this.nextNote=this.ctx.currentTime+(this.mood==='uneasy'?9:16);const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=hz[(s.time+1)%3]*4;g.gain.setValueAtTime(.0001,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.018,this.ctx.currentTime+1);g.gain.exponentialRampToValueAtTime(.0001,this.ctx.currentTime+6);o.connect(g);g.connect(this.musicGain);o.start();o.stop(this.ctx.currentTime+7);},
 radio(){const s=getSettings();if(!s.sound||s.radio===false||s.volume<=0||!this.ctx||this.ctx.state==='suspended'||document.hidden)return;const ctx=this.ctx,now=ctx.currentTime;if(this.lastRadio!=null&&now-this.lastRadio<.7)return;this.lastRadio=now;const buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*.22),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1);const noise=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();noise.buffer=buffer;f.type='bandpass';f.frequency.value=1600;f.Q.value=.8;g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(.065*s.volume,now+.012);g.gain.exponentialRampToValueAtTime(.0001,now+.22);noise.connect(f);f.connect(g);g.connect(ctx.destination);noise.start(now);noise.stop(now+.23);for(const [i,hz] of [1120,1480].entries()){const o=ctx.createOscillator(),v=ctx.createGain(),at=now+.06+i*.075;o.type='sine';o.frequency.value=hz;v.gain.setValueAtTime(.0001,at);v.gain.linearRampToValueAtTime(.045*s.volume,at+.008);v.gain.exponentialRampToValueAtTime(.0001,at+.055);o.connect(v);v.connect(ctx.destination);o.start(at);o.stop(at+.065);}},
 click(){const s=getSettings();if(!s.sound||s.volume<=0||!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.setValueAtTime(650,this.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(340,this.ctx.currentTime+.07);g.gain.setValueAtTime(.02*s.volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+.08);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+.08);}
};}
